import{z as i,x as A,o as E,c as C,q as s,j as l,D as e,d as n,s as r,S as h,b as o}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"ChaCha20","description":"","frontmatter":{"title":"ChaCha20","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/chacha20.md","filePath":"cs/chacha20.md","lastUpdated":1791413859000}'),c={name:"cs/chacha20.md"};function d(p,a,B,S,m,f){const t=A("Mermaid");return E(),C("div",null,[a[2]||(a[2]=s('<h1 id="chacha20" tabindex="-1">ChaCha20 <a class="header-anchor" href="#chacha20" aria-label="Permalink to &quot;ChaCha20&quot;">​</a></h1><div class="epigraph"><p>ChaCha 用加、循环移位与异或在软件里造密钥流：没有 S 盒查表，缓存定时更老实。它仍是计算安全的 PRG 式构造，密钥与 nonce 合同与 AES 一样严格。</p><footer>—— Bernstein, ChaCha, a variant of Salsa20；RFC 8439（ChaCha20-Poly1305）</footer></div><p>上一课<a href="/cs/feistel-des">Feistel 与 DES</a>说明旧分组密码的结构债。缺口是<strong>软件平台上的流密码</strong>：AES 在无 AES-NI 时易因查表泄漏，ChaCha 用 ARX 躲开这张表。不重写一次一密，也不把「无表」写成完善保密。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>AES 课的 S 盒在软件里常是内存查表，命中模式可当侧信道。<a href="/cs/side-channel">侧信道直觉</a>已警告计时；本课落到候选：ChaCha20 把 256 比特密钥、96 比特 nonce、32 比特计数器扩成密钥流，再与明文异或。Poly1305 在 RFC 8439 里补 MAC。缺口是 ARX 流密码的合同，不是又一个 SPN。</p><p><span class="marginnote">术语翻译：ARX 就是 Addition、Rotation、XOR 三种运算的缩写——CPU 上三条最便宜的整数指令；PRG（伪随机数发生器）在这里指「把 256 位密钥拉成任意长的、看起来随机的密钥流」。没有查表、没有乘法，缓存与时序就没什么可泄漏的。</span></p><h3 id="nonce-仍不能复用" tabindex="-1">nonce 仍不能复用 <a class="header-anchor" href="#nonce-仍不能复用" aria-label="Permalink to &quot;nonce 仍不能复用&quot;">​</a></h3><p>流密码异或与一次一密同形，复用 nonce 则两段明文之差泄漏。ChaCha 不赦免这条。</p><p><span class="marginnote">Bernstein 的 Salsa20/ChaCha。TLS 1.3 与许多移动实现选 ChaCha20-Poly1305 当 AES-GCM 的软件备胎。本课不写利用缓存的测量步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>描述状态矩阵：常数、密钥、计数、nonce。四分之一圈的 ARX。计数器模式式的块编号给出可寻址密钥流。对照 AES-CTR：同是 PRG 用法，置换族不同。</p><p><span class="marginnote">数字实例：每个密钥流块 64 字节，计数器就是块编号——要加密第 1000 块，直接把计数器设成 1000 算一块，不必先算前 999 块。这就是「可寻址密钥流」：随机写、随机读、并行加密都成立，也正因如此每个块必须用不同的计数值。</span></p><p><span class="marginnote">常见误区：「没有查表」不等于「更安全」——它只是把缓存侧信道关掉，安全性等级与 AES 一样是计算安全的；nonce 复用的灾难也不会因此赦免。同样别把「流密码很快」当普遍结论：有 AES-NI 的机器上 AES-GCM 往往反超。</span></p>',14)),(E(),l(h,null,{default:e(()=>[r(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20ST%5B%22%E7%8A%B6%E6%80%81%3A%20%E5%AF%86%E9%92%A5%20nonce%20%E8%AE%A1%E6%95%B0%22%5D%20--%3E%20ARX%5B%22ARX%20%E5%9B%9B%E5%88%86%E4%B9%8B%E4%B8%80%E5%9C%88%22%5D%0A%20%20%20%20ARX%20--%3E%20KS%5B%22%E5%AF%86%E9%92%A5%E6%B5%81%E5%9D%97%22%5D%0A%20%20%20%20KS%20--%3E%20XOR%5B%22%E4%B8%8E%E6%98%8E%E6%96%87%E5%BC%82%E6%88%96%22%5D%0A%20%20%20%20XOR%20--%3E%20CT%5B%22%E5%AF%86%E6%96%87%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[n("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,"作为 PRG，ChaCha 把短密钥拉成密钥流；完整性要另配 Poly1305 或走 AEAD 包装。它不替代公钥，不替代证书。CPU 有 AES-NI 时 AES-GCM 常更快；无硬件时 ChaCha 更可预测。二者都是计算安全候选。",-1)),(E(),l(h,null,{default:e(()=>[r(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20K1%5B%22%E5%AF%86%E9%92%A5%2Bnonce%20%E7%94%9F%E6%88%90%E5%AF%86%E9%92%A5%E6%B5%81%20KS%22%5D%20--%3E%20C1%5B%22%E5%AF%86%E6%96%87%E4%B8%80%20%3D%20%E6%98%8E%E6%96%87%E4%B8%80%20XOR%20KS%22%5D%0A%20%20K2%5B%22%E5%90%8C%E4%B8%80%E5%AF%86%E9%92%A5%2B%E5%90%8C%E4%B8%80%20nonce%22%5D%20--%3E%7C%22%E7%94%9F%E6%88%90%E5%90%8C%E4%B8%80%E6%9D%A1%E5%AF%86%E9%92%A5%E6%B5%81%22%7C%20C2%5B%22%E5%AF%86%E6%96%87%E4%BA%8C%20%3D%20%E6%98%8E%E6%96%87%E4%BA%8C%20XOR%20KS%22%5D%0A%20%20C1%20--%3E%20X%5B%22%E4%B8%A4%E5%AF%86%E6%96%87%E5%BC%82%E6%88%96%EF%BC%9AKS%20%E6%8A%B5%E6%B6%88%22%5D%0A%20%20C2%20--%3E%20X%0A%20%20X%20--%3E%20LEAK%5B%22%E5%BE%97%E5%88%B0%20%E6%98%8E%E6%96%87%E4%B8%80%20XOR%20%E6%98%8E%E6%96%87%E4%BA%8C%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=s('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Salsa 族全部变体列成菜单。AEAD 如何把保密与认证收成一次调用，下一课进 GCM 内部——ChaCha-Poly 是平行实例，机制课以 GCM 为解剖对象。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DES 对照之后，软件向密钥流选 ARX。</li><li>ChaCha20：无 S 盒表，计数器编址密钥流。</li><li>复用 nonce 与一次一密复用密钥同类失败。</li><li>下一课解剖 AEAD，以 GCM 为内部。</li><li>出处：Bernstein, ChaCha；RFC 8439；对照 Salsa20。</li></ul>',4))])}const u=i(c,[["render",d]]);export{_ as __pageData,u as default};
